"""The native writers' shared fixture stays generated by Python's own record, timing and trail code (plan native-g2
step 4, N2-5). CTest `native_records` checks that the C++ writers reproduce it byte for byte."""

import importlib.util
import json
from pathlib import Path

from motionman import records

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("native_records_fixture", ROOT / "tools/native_records/make_fixture.py")
make_fixture = importlib.util.module_from_spec(spec)
spec.loader.exec_module(make_fixture)


def test_committed_fixture_is_exactly_what_python_writes_today():
    committed = make_fixture.FIXTURE.read_text(encoding="utf-8")
    assert committed == make_fixture.dump(make_fixture.build()), "run tools/native_records/make_fixture.py --write"


def test_fixture_lines_are_valid_records_and_cover_the_edge_cases():
    doc = json.loads(make_fixture.FIXTURE.read_text(encoding="utf-8"))
    lines = [c["line"] for c in doc["records"] if c["line"] is not None]
    parsed = [records.parse_line(line) for line in lines]
    assert all(not r.get("legacy") for r in parsed)
    assert sum(c["line"] is None for c in doc["records"]) == 3  # overrun, zero width, non-finite
    objects = [o for r in parsed for o in r["objects"]]
    assert any(o["track_id"] is None for o in objects) and any(o["track_id"] is not None for o in objects)
    tie = parsed[2]["objects"][0]["bbox_xyxy"]
    assert tie == [0.12, 0.38, 2.67, 4.62]  # half-even on exact ties; 2.675 is just below in binary
    assert '"bbox_xyxy": [0.0, -0.0, 10.0, 10.0]' in lines[4]  # Python keeps -0.0; the native writer must too


def test_timing_rows_keep_the_legacy_shape_with_native_stage_names():
    doc = json.loads(make_fixture.FIXTURE.read_text(encoding="utf-8"))
    row = json.loads(doc["timings"][0]["line"])
    assert list(row) == ["source_frame_index", "decode_ms", "preprocess_ms", "infer_ms", "track_ms", "render_ms",
                         "write_ms"]  # fmt: skip
    assert row["decode_ms"] == 0.001 and row["render_ms"] == 1234.568


def test_trail_checkpoints_show_the_cap_return_and_expiry():
    frames = json.loads(make_fixture.FIXTURE.read_text(encoding="utf-8"))["trails"]
    assert {k: len(v) for k, v in frames[29]["points"].items()} == {"1": 30, "2": 30, "3": 30}
    assert len(frames[70]["points"]["2"]) == 30  # ID 2 was hidden 30 frames (< 60) and kept its trail
    assert "3" in frames[108]["points"] and "3" not in frames[109]["points"]  # last seen 49, dropped at 49 + 60
